// Expr is the Go interface backing the Gom sort Expr.
type Expr interface {
	sharedobjects.Term
	isExpr()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	Isiltrue() bool
	Isilfalse() bool
	Isisfsym() bool
	Iseq() bool
	Istisfsym() bool
	Isteq() bool
	Isiland() bool
	Isilor() bool
	Isilnot() bool
	IsappSubsE() bool
	GetSubst() SubstitutionList
	GetT() Term
	GetSymbol() Symbol
	GetLt() Term
	GetRt() Term
	GetAbst() AbsTerm
	GetLabst() AbsTerm
	GetRabst() AbsTerm
	GetLeft() Expr
	GetRight() Expr
	GetExp() Expr
	GetSubs() SubstitutionList
	GetE() Expr
	Length() int
	Reverse() Expr
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// ExprFromTerm is Java Gom's Expr.fromTerm(trm).
func ExprFromTerm(trm aterm.ATerm) Expr { return ExprFromTermConv(trm, aterm.IdConverter{}) }

// ExprFromTermConv is Java Gom's Expr.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func ExprFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) Expr {
	converted := conv.Convert(trm)
	var results []Expr
	if r, ok := fromTermIltrueExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIlfalseExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIsfsymExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermEqExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermTisfsymExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermTeqExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIlandExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIlorExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIlnotExpr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermAppSubsEExpr(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a Expr", trm), IllegalArgument: true})
	}
	return results[0]
}

// ExprFromString is Java Gom's Expr.fromString(s).
func ExprFromString(s string) Expr { return ExprFromTerm(aterm.GetInstance().Parse(s)) }

// ExprFromStream is Java Gom's Expr.fromStream(stream) (an IOException is
// the error).
func ExprFromStream(stream io.Reader) (Expr, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return ExprFromTerm(at), nil
}

