func (t *TeqExpr) CompareTo(o any) int {
	ao := o.(Expr)
	if ao == Expr(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*TeqExpr)
	if c := t.Labst.CompareTo(tco.Labst); c != 0 {
		return c
	}
	if c := t.Rabst.CompareTo(tco.Rabst); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

