// InstrFromTerm is Java Gom's Instr.fromTerm(trm).
func InstrFromTerm(trm aterm.ATerm) Instr { return InstrFromTermConv(trm, aterm.IdConverter{}) }

// InstrFromTermConv is Java Gom's Instr.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func InstrFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) Instr {
	converted := conv.Convert(trm)
	var results []Instr
	if r, ok := fromTermAcceptInstr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermRefuseInstr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermITEInstr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermILLetInstr(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermSequenceInstr(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a Instr", trm), IllegalArgument: true})
	}
	return results[0]
}

// InstrFromString is Java Gom's Instr.fromString(s).
func InstrFromString(s string) Instr { return InstrFromTerm(aterm.GetInstance().Parse(s)) }

// InstrFromStream is Java Gom's Instr.fromStream(stream) (an IOException is
// the error).
func InstrFromStream(stream io.Reader) (Instr, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return InstrFromTerm(at), nil
}

