func (s *VisitILLet) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ILLetInstr); !ok {
		return sl.StatusFailure
	}
	if len(s.args) != 3 {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, false)
}
