// InstrList is the Go interface backing the Gom sort InstrList.
type InstrList interface {
	sharedobjects.Term
	isInstrList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConssemicolon() bool
	IsEmptysemicolon() bool
	GetHeadsemicolon() Instr
	GetTailsemicolon() InstrList
	Length() int
	Reverse() InstrList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// InstrListFromTerm is Java Gom's InstrList.fromTerm(trm).
func InstrListFromTerm(trm aterm.ATerm) InstrList {
	return InstrListFromTermConv(trm, aterm.IdConverter{})
}

// InstrListFromTermConv is Java Gom's InstrList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func InstrListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) InstrList {
	converted := conv.Convert(trm)
	var results []InstrList
	if r, ok := fromTermSemicolonInstrList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a InstrList", trm), IllegalArgument: true})
	}
	return results[0]
}

// InstrListFromString is Java Gom's InstrList.fromString(s).
func InstrListFromString(s string) InstrList { return InstrListFromTerm(aterm.GetInstance().Parse(s)) }

// InstrListFromStream is Java Gom's InstrList.fromStream(stream) (an IOException is
// the error).
func InstrListFromStream(stream io.Reader) (InstrList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return InstrListFromTerm(at), nil
}

// SemicolonInstrList is the term type of the variadic operator `semicolon(...)` of sort InstrList
// (Java's abstract class semicolon): a maximally-shared cons cell (Java's
// Conssemicolon: a head and a tail) or the empty list (Java's Emptysemicolon).
type SemicolonInstrList struct {
	head  Instr
	tail  InstrList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*SemicolonInstrList) isInstrList() {}

func (t *SemicolonInstrList) Hash() uint32 { return t.hash }

func (t *SemicolonInstrList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*SemicolonInstrList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *SemicolonInstrList) Duplicate() sharedobjects.Term {
	return &SemicolonInstrList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Instr[]{}): a last tail
// that is not a list (of sort InstrList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *SemicolonInstrList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur InstrList = t
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*SemicolonInstrList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a semicolon list is not a Instr", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *SemicolonInstrList) ChildCount() int { return len(t.elements()) }

func (t *SemicolonInstrList) ChildAt(i int) any { return t.elements()[i] }

func (t *SemicolonInstrList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *SemicolonInstrList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: SemicolonFromArray(children).
func (t *SemicolonInstrList) SetChildren(children []any) any {
	args := make([]Instr, len(children))
	for i, c := range children {
		args[i] = c.(Instr)
	}
	return MakeSemicolon(args...)
}

func (t *SemicolonInstrList) String() string {
	var b strings.Builder
	b.WriteString("semicolon(")
	var cur InstrList = t
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsSemicolon is Java Gom's Conssemicolon.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsSemicolon(head Instr, tail InstrList) InstrList {
	proto := &SemicolonInstrList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Conssemicolon"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*SemicolonInstrList)
}

// realMakeEmptySemicolon is Java Gom's Emptysemicolon.realMake: the shared empty list,
// without hook.
func realMakeEmptySemicolon() InstrList {
	proto := &SemicolonInstrList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Emptysemicolon"), nil)}
	return factory.Build(proto).(*SemicolonInstrList)
}

// RawSemicolon builds the semicolon list holding exactly args, without construction
// hook.
func RawSemicolon(args ...Instr) InstrList {
	l := realMakeEmptySemicolon()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsSemicolon(args[i], l)
	}
	return l
}

// EmptySemicolon is Java Gom's Emptysemicolon.make(): the empty semicolon list, after the
// construction hooks.
func EmptySemicolon() InstrList {
	return realMakeEmptySemicolon()
}

// ConsSemicolon is Java Gom's Conssemicolon.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsSemicolon(head Instr, tail InstrList) InstrList {
	return RealMakeConsSemicolon(head, tail)
}

// MakeSemicolon builds the list of args as Tom's `semicolon(args…)` does: from EmptySemicolon,
// by ConsSemicolon, through the construction hooks (Java's semicolon.fromArray).
func MakeSemicolon(args ...Instr) InstrList {
	var l InstrList = EmptySemicolon()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsSemicolon(args[i], l)
	}
	return l
}

// SemicolonFromArray is Java Gom's semicolon.fromArray(array).
func SemicolonFromArray(array []Instr) InstrList { return MakeSemicolon(array...) }

// IsSemicolon is the `Is_semicolon` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `semicolon` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsSemicolon struct{ sl.AbstractStrategy }

func (IsSemicolon) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*SemicolonInstrList); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsSemicolon) ChildCount() int             { return 0 }
func (IsSemicolon) ChildAt(int) sl.Strategy     { panic("IsSemicolon: no children") }
func (IsSemicolon) SetChildAt(int, sl.Strategy) { panic("IsSemicolon: no children") }
func (s *IsSemicolon) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*SemicolonInstrList); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsSemicolon) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsSemicolon) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsSemicolon)(nil)

// VisitSemicolon is the `_semicolon` slot-visit strategy: when subject is `semicolon`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `semicolon`.
type VisitSemicolon struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitSemicolon builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitSemicolon(args ...sl.Strategy) *VisitSemicolon {
	return &VisitSemicolon{args: args}
}

func (s *VisitSemicolon) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*SemicolonInstrList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitSemicolon) ChildCount() int                 { return len(s.args) }
func (s *VisitSemicolon) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitSemicolon) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitSemicolon) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*SemicolonInstrList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitSemicolon) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitSemicolon) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitSemicolon)(nil)

// SymbolName is the symbol of the Java term: Conssemicolon or Emptysemicolon.
func (t *SemicolonInstrList) SymbolName() string {
	if t.empty {
		return "Emptysemicolon"
	}
	return "Conssemicolon"
}

func (t *SemicolonInstrList) IsConssemicolon() bool  { return !t.empty }
func (t *SemicolonInstrList) IsEmptysemicolon() bool { return t.empty }

func (t *SemicolonInstrList) GetHeadsemicolon() Instr {
	if t.empty {
		panic(&aterm.GomError{Msg: "This InstrList has no Headsemicolon"})
	}
	return t.head
}
func (t *SemicolonInstrList) GetTailsemicolon() InstrList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This InstrList has no Tailsemicolon"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a semicolon list counts as one element).
func (t *SemicolonInstrList) Length() int {
	res := 0
	var tl InstrList = t
	for {
		c, ok := tl.(*SemicolonInstrList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*SemicolonInstrList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a semicolon list.
func (t *SemicolonInstrList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur InstrList = t
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*SemicolonInstrList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsSemicolon
// (through the hooks).
func (t *SemicolonInstrList) Reverse() InstrList {
	if t.empty {
		return t
	}
	var cur InstrList = t
	var rev InstrList = EmptySemicolon()
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok || c.empty {
			break
		}
		rev = ConsSemicolon(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsSemicolon (through the hooks).
func (t *SemicolonInstrList) Append(element Instr) InstrList {
	var heads []Instr
	var cur InstrList = t
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res InstrList
	if c, ok := cur.(*SemicolonInstrList); ok && c.empty {
		res = ConsSemicolon(element, cur)
	} else {
		res = ConsSemicolon(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsSemicolon(heads[i], res)
	}
	return res
}

func (t *SemicolonInstrList) CompareTo(o any) int {
	for {
		ao := o.(InstrList)
		if ao == InstrList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*SemicolonInstrList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*SemicolonInstrList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *SemicolonInstrList) CompareToLPO(o any) int {
	for {
		ao := o.(InstrList)
		if ao == InstrList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*SemicolonInstrList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*SemicolonInstrList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *SemicolonInstrList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Instr
	var cur InstrList = t
	for {
		c, ok := cur.(*SemicolonInstrList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*SemicolonInstrList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermSemicolonInstrList is Java Gom's semicolon.fromTerm: an application of semicolon, or a
// list (of ToATerm), of convertible elements.
func fromTermSemicolonInstrList(trm aterm.ATerm, conv aterm.ATermConverter) (res InstrList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "semicolon" {
		elems := make([]Instr, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = InstrFromTermConv(a, conv)
		}
		return MakeSemicolon(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a semicolon (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Instr
		for !list.IsEmpty() {
			elems = append(elems, InstrFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeSemicolon(elems...), true
	}
	return nil, false
}

// Substitution is the Go interface backing the Gom sort Substitution.
type Substitution interface {
	sharedobjects.Term
	isSubstitution()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	Isundefsubs() bool
	Isis() bool
	GetVar() Variable
	GetTerm() Term
	Length() int
	Reverse() Substitution
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// SubstitutionFromTerm is Java Gom's Substitution.fromTerm(trm).
func SubstitutionFromTerm(trm aterm.ATerm) Substitution {
	return SubstitutionFromTermConv(trm, aterm.IdConverter{})
}

// SubstitutionFromTermConv is Java Gom's Substitution.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func SubstitutionFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) Substitution {
	converted := conv.Convert(trm)
	var results []Substitution
	if r, ok := fromTermUndefsubsSubstitution(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermIsSubstitution(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a Substitution", trm), IllegalArgument: true})
	}
	return results[0]
}

// SubstitutionFromString is Java Gom's Substitution.fromString(s).
func SubstitutionFromString(s string) Substitution {
	return SubstitutionFromTerm(aterm.GetInstance().Parse(s))
}

// SubstitutionFromStream is Java Gom's Substitution.fromStream(stream) (an IOException is
// the error).
func SubstitutionFromStream(stream io.Reader) (Substitution, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return SubstitutionFromTerm(at), nil
}

