// fromTermUndefsubsSubstitution is Java Gom's undefsubs.fromTerm: an unquoted application of
// undefsubs whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermUndefsubsSubstitution(trm aterm.ATerm, conv aterm.ATermConverter) (Substitution, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "undefsubs" && !appl.GetAFun().IsQuoted() {
		return MakeUndefsubs(), true
	}
	return nil, false
}

// IsSubstitution is the term type for the alternative `is(...)` of sort Substitution.
type IsSubstitution struct {
	Var  Variable
	Term Term
	hash uint32
}

func (*IsSubstitution) isSubstitution() {}

func (t *IsSubstitution) Hash() uint32 { return t.hash }

func (t *IsSubstitution) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*IsSubstitution)
	if !ok {
		return false
	}
	if t.Var != o.Var {
		return false
	}
	if t.Term != o.Term {
		return false
	}
	return true
}

func (t *IsSubstitution) Duplicate() sharedobjects.Term {
	clone := *t
	return &clone
}

func (t *IsSubstitution) String() string {
	return "is(" + fmt.Sprint(t.Var) + "," + fmt.Sprint(t.Term) + ")"
}

func (t *IsSubstitution) ChildCount() int { return 2 }

func (t *IsSubstitution) ChildAt(i int) any {
	switch i {
	case 0:
		return t.Var
	case 1:
		return t.Term
	}
	panic(fmt.Sprintf("IsSubstitution.ChildAt: index %d out of range", i))
}

func (t *IsSubstitution) SetChildAt(i int, child any) any {
	switch i {
	case 0:
		return MakeIs(child.(Variable), t.Term)
	case 1:
		return MakeIs(t.Var, child.(Term))
	}
	panic(fmt.Sprintf("IsSubstitution.SetChildAt: index %d out of range", i))
}

func (t *IsSubstitution) Children() []any {
	return []any{t.Var, t.Term}
}

func (t *IsSubstitution) SetChildren(children []any) any {
	return MakeIs(children[0].(Variable), children[1].(Term))
}

// MakeIs builds the canonical (shared) is term.
func MakeIs(var_ Variable, term Term) Substitution {
	hashes := []uint32{var_.Hash(), term.Hash()}
	proto := &IsSubstitution{hash: sharedobjects.MixSymbol(sharedobjects.StringHash("is"), hashes), Var: var_, Term: term}
	return factory.Build(proto).(*IsSubstitution)
}

// IsIs is the `Is_is` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `is` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsIs struct{ sl.AbstractStrategy }

func (IsIs) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*IsSubstitution); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsIs) ChildCount() int             { return 0 }
func (IsIs) ChildAt(int) sl.Strategy     { panic("IsIs: no children") }
func (IsIs) SetChildAt(int, sl.Strategy) { panic("IsIs: no children") }
func (s *IsIs) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*IsSubstitution); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsIs) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsIs) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsIs)(nil)

// VisitIs is the `_is` slot-visit strategy: when subject is `is`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `is`.
type VisitIs struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitIs builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitIs(args ...sl.Strategy) *VisitIs {
	return &VisitIs{args: args}
}

func (s *VisitIs) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*IsSubstitution); !ok {
		return subject, sl.ErrVisitFailure
	}
	if len(s.args) != 2 {
		return subject, sl.ErrVisitFailure
	}
	var newChildren []any
	for i := 0; i < 2; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[i].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitIs) ChildCount() int                 { return len(s.args) }
func (s *VisitIs) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitIs) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitIs) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*IsSubstitution); !ok {
		return sl.StatusFailure
	}
	if len(s.args) != 2 {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, false)
}
func (s *VisitIs) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitIs) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitIs)(nil)

func (t *IsSubstitution) SymbolName() string { return "is" }

func (t *IsSubstitution) Isundefsubs() bool { return false }
func (t *IsSubstitution) Isis() bool        { return true }

func (t *IsSubstitution) GetVar() Variable { return t.Var }
func (t *IsSubstitution) GetTerm() Term    { return t.Term }

func (t *IsSubstitution) Length() int {
	panic(&aterm.GomError{Msg: "This Substitution.is is not a list", IllegalArgument: true})
}

func (t *IsSubstitution) Reverse() Substitution {
	panic(&aterm.GomError{Msg: "This Substitution.is is not a list", IllegalArgument: true})
}

func (t *IsSubstitution) CompareTo(o any) int {
	ao := o.(Substitution)
	if ao == Substitution(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsSubstitution)
	if c := t.Var.CompareTo(tco.Var); c != 0 {
		return c
	}
	if c := t.Term.CompareTo(tco.Term); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *IsSubstitution) CompareToLPO(o any) int {
	ao := o.(Substitution)
	if ao == Substitution(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*IsSubstitution)
	if c := t.Var.CompareToLPO(tco.Var); c != 0 {
		return c
	}
	if c := t.Term.CompareToLPO(tco.Term); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

// ToATerm is the ATerm of the term: an application of is.
func (t *IsSubstitution) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	return f.MakeAppl(f.MakeAFun("is", 2, false), t.Var.ToATerm(), t.Term.ToATerm())
}

// fromTermIsSubstitution is Java Gom's is.fromTerm: an unquoted application of
// is whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermIsSubstitution(trm aterm.ATerm, conv aterm.ATermConverter) (Substitution, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "is" && !appl.GetAFun().IsQuoted() {
		return MakeIs(VariableFromTermConv(appl.GetArgument(0), conv), TermFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

// SubstitutionList is the Go interface backing the Gom sort SubstitutionList.
type SubstitutionList interface {
	sharedobjects.Term
	isSubstitutionList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConssubs() bool
	IsEmptysubs() bool
	GetHeadsubs() Substitution
	GetTailsubs() SubstitutionList
	Length() int
	Reverse() SubstitutionList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// SubstitutionListFromTerm is Java Gom's SubstitutionList.fromTerm(trm).
func SubstitutionListFromTerm(trm aterm.ATerm) SubstitutionList {
	return SubstitutionListFromTermConv(trm, aterm.IdConverter{})
}

// SubstitutionListFromTermConv is Java Gom's SubstitutionList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func SubstitutionListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) SubstitutionList {
	converted := conv.Convert(trm)
	var results []SubstitutionList
	if r, ok := fromTermSubsSubstitutionList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a SubstitutionList", trm), IllegalArgument: true})
	}
	return results[0]
}

// SubstitutionListFromString is Java Gom's SubstitutionList.fromString(s).
func SubstitutionListFromString(s string) SubstitutionList {
	return SubstitutionListFromTerm(aterm.GetInstance().Parse(s))
}

// SubstitutionListFromStream is Java Gom's SubstitutionList.fromStream(stream) (an IOException is
// the error).
func SubstitutionListFromStream(stream io.Reader) (SubstitutionList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return SubstitutionListFromTerm(at), nil
}

// SubsSubstitutionList is the term type of the variadic operator `subs(...)` of sort SubstitutionList
// (Java's abstract class subs): a maximally-shared cons cell (Java's
// Conssubs: a head and a tail) or the empty list (Java's Emptysubs).
type SubsSubstitutionList struct {
	head  Substitution
	tail  SubstitutionList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*SubsSubstitutionList) isSubstitutionList() {}

func (t *SubsSubstitutionList) Hash() uint32 { return t.hash }

func (t *SubsSubstitutionList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*SubsSubstitutionList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *SubsSubstitutionList) Duplicate() sharedobjects.Term {
	return &SubsSubstitutionList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Substitution[]{}): a last tail
// that is not a list (of sort SubstitutionList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *SubsSubstitutionList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur SubstitutionList = t
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*SubsSubstitutionList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a subs list is not a Substitution", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *SubsSubstitutionList) ChildCount() int { return len(t.elements()) }

func (t *SubsSubstitutionList) ChildAt(i int) any { return t.elements()[i] }

func (t *SubsSubstitutionList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *SubsSubstitutionList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: SubsFromArray(children).
func (t *SubsSubstitutionList) SetChildren(children []any) any {
	args := make([]Substitution, len(children))
	for i, c := range children {
		args[i] = c.(Substitution)
	}
	return MakeSubs(args...)
}

func (t *SubsSubstitutionList) String() string {
	var b strings.Builder
	b.WriteString("subs(")
	var cur SubstitutionList = t
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsSubs is Java Gom's Conssubs.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsSubs(head Substitution, tail SubstitutionList) SubstitutionList {
	proto := &SubsSubstitutionList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Conssubs"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*SubsSubstitutionList)
}

// realMakeEmptySubs is Java Gom's Emptysubs.realMake: the shared empty list,
// without hook.
func realMakeEmptySubs() SubstitutionList {
	proto := &SubsSubstitutionList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("Emptysubs"), nil)}
	return factory.Build(proto).(*SubsSubstitutionList)
}

// RawSubs builds the subs list holding exactly args, without construction
// hook.
func RawSubs(args ...Substitution) SubstitutionList {
	l := realMakeEmptySubs()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsSubs(args[i], l)
	}
	return l
}

// EmptySubs is Java Gom's Emptysubs.make(): the empty subs list, after the
// construction hooks.
func EmptySubs() SubstitutionList {
	return realMakeEmptySubs()
}

// ConsSubs is Java Gom's Conssubs.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsSubs(head Substitution, tail SubstitutionList) SubstitutionList {
	return RealMakeConsSubs(head, tail)
}

// MakeSubs builds the list of args as Tom's `subs(args…)` does: from EmptySubs,
// by ConsSubs, through the construction hooks (Java's subs.fromArray).
func MakeSubs(args ...Substitution) SubstitutionList {
	var l SubstitutionList = EmptySubs()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsSubs(args[i], l)
	}
	return l
}

// SubsFromArray is Java Gom's subs.fromArray(array).
func SubsFromArray(array []Substitution) SubstitutionList { return MakeSubs(array...) }

// IsSubs is the `Is_subs` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `subs` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsSubs struct{ sl.AbstractStrategy }

func (IsSubs) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*SubsSubstitutionList); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsSubs) ChildCount() int             { return 0 }
func (IsSubs) ChildAt(int) sl.Strategy     { panic("IsSubs: no children") }
func (IsSubs) SetChildAt(int, sl.Strategy) { panic("IsSubs: no children") }
func (s *IsSubs) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*SubsSubstitutionList); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsSubs) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsSubs) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsSubs)(nil)

// VisitSubs is the `_subs` slot-visit strategy: when subject is `subs`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `subs`.
type VisitSubs struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitSubs builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitSubs(args ...sl.Strategy) *VisitSubs {
	return &VisitSubs{args: args}
}

func (s *VisitSubs) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*SubsSubstitutionList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitSubs) ChildCount() int                 { return len(s.args) }
func (s *VisitSubs) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitSubs) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitSubs) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*SubsSubstitutionList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitSubs) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitSubs) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitSubs)(nil)

// SymbolName is the symbol of the Java term: Conssubs or Emptysubs.
func (t *SubsSubstitutionList) SymbolName() string {
	if t.empty {
		return "Emptysubs"
	}
	return "Conssubs"
}

func (t *SubsSubstitutionList) IsConssubs() bool  { return !t.empty }
func (t *SubsSubstitutionList) IsEmptysubs() bool { return t.empty }

func (t *SubsSubstitutionList) GetHeadsubs() Substitution {
	if t.empty {
		panic(&aterm.GomError{Msg: "This SubstitutionList has no Headsubs"})
	}
	return t.head
}
func (t *SubsSubstitutionList) GetTailsubs() SubstitutionList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This SubstitutionList has no Tailsubs"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a subs list counts as one element).
func (t *SubsSubstitutionList) Length() int {
	res := 0
	var tl SubstitutionList = t
	for {
		c, ok := tl.(*SubsSubstitutionList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*SubsSubstitutionList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a subs list.
func (t *SubsSubstitutionList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur SubstitutionList = t
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*SubsSubstitutionList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsSubs
// (through the hooks).
func (t *SubsSubstitutionList) Reverse() SubstitutionList {
	if t.empty {
		return t
	}
	var cur SubstitutionList = t
	var rev SubstitutionList = EmptySubs()
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok || c.empty {
			break
		}
		rev = ConsSubs(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsSubs (through the hooks).
func (t *SubsSubstitutionList) Append(element Substitution) SubstitutionList {
	var heads []Substitution
	var cur SubstitutionList = t
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res SubstitutionList
	if c, ok := cur.(*SubsSubstitutionList); ok && c.empty {
		res = ConsSubs(element, cur)
	} else {
		res = ConsSubs(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsSubs(heads[i], res)
	}
	return res
}

func (t *SubsSubstitutionList) CompareTo(o any) int {
	for {
		ao := o.(SubstitutionList)
		if ao == SubstitutionList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*SubsSubstitutionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*SubsSubstitutionList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *SubsSubstitutionList) CompareToLPO(o any) int {
	for {
		ao := o.(SubstitutionList)
		if ao == SubstitutionList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*SubsSubstitutionList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*SubsSubstitutionList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *SubsSubstitutionList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Substitution
	var cur SubstitutionList = t
	for {
		c, ok := cur.(*SubsSubstitutionList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*SubsSubstitutionList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermSubsSubstitutionList is Java Gom's subs.fromTerm: an application of subs, or a
// list (of ToATerm), of convertible elements.
func fromTermSubsSubstitutionList(trm aterm.ATerm, conv aterm.ATermConverter) (res SubstitutionList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "subs" {
		elems := make([]Substitution, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = SubstitutionFromTermConv(a, conv)
		}
		return MakeSubs(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a subs (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Substitution
		for !list.IsEmpty() {
			elems = append(elems, SubstitutionFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeSubs(elems...), true
	}
	return nil, false
}

