func (t *EnvEnvironment) CompareTo(o any) int {
	ao := o.(Environment)
	if ao == Environment(t) {
		return 0
	}
	if t.Hash() != ao.Hash() {
		if t.Hash() < ao.Hash() {
			return -1
		}
		return 1
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*EnvEnvironment)
	if c := t.Subs.CompareTo(tco.Subs); c != 0 {
		return c
	}
	if c := t.I.CompareTo(tco.I); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

func (t *EnvEnvironment) CompareToLPO(o any) int {
	ao := o.(Environment)
	if ao == Environment(t) {
		return 0
	}
	if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
		return c
	}
	tco := ao.(*EnvEnvironment)
	if c := t.Subs.CompareToLPO(tco.Subs); c != 0 {
		return c
	}
	if c := t.I.CompareToLPO(tco.I); c != 0 {
		return c
	}
	panic(&aterm.GomError{Msg: "Unable to compare"})
}

