// TermList is the Go interface backing the Gom sort TermList.
type TermList interface {
	sharedobjects.Term
	isTermList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConsconcTerm() bool
	IsEmptyconcTerm() bool
	GetHeadconcTerm() Term
	GetTailconcTerm() TermList
	Length() int
	Reverse() TermList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// TermListFromTerm is Java Gom's TermList.fromTerm(trm).
func TermListFromTerm(trm aterm.ATerm) TermList {
	return TermListFromTermConv(trm, aterm.IdConverter{})
}

// TermListFromTermConv is Java Gom's TermList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func TermListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) TermList {
	converted := conv.Convert(trm)
	var results []TermList
	if r, ok := fromTermConcTermTermList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a TermList", trm), IllegalArgument: true})
	}
	return results[0]
}

// TermListFromString is Java Gom's TermList.fromString(s).
func TermListFromString(s string) TermList { return TermListFromTerm(aterm.GetInstance().Parse(s)) }

// TermListFromStream is Java Gom's TermList.fromStream(stream) (an IOException is
// the error).
func TermListFromStream(stream io.Reader) (TermList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return TermListFromTerm(at), nil
}

// ConcTermTermList is the term type of the variadic operator `concTerm(...)` of sort TermList
// (Java's abstract class concTerm): a maximally-shared cons cell (Java's
// ConsconcTerm: a head and a tail) or the empty list (Java's EmptyconcTerm).
type ConcTermTermList struct {
	head  Term
	tail  TermList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcTermTermList) isTermList() {}

func (t *ConcTermTermList) Hash() uint32 { return t.hash }

func (t *ConcTermTermList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcTermTermList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcTermTermList) Duplicate() sharedobjects.Term {
	return &ConcTermTermList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Term[]{}): a last tail
// that is not a list (of sort TermList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcTermTermList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur TermList = t
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcTermTermList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concTerm list is not a Term", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcTermTermList) ChildCount() int { return len(t.elements()) }

func (t *ConcTermTermList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcTermTermList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcTermTermList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcTermFromArray(children).
func (t *ConcTermTermList) SetChildren(children []any) any {
	args := make([]Term, len(children))
	for i, c := range children {
		args[i] = c.(Term)
	}
	return MakeConcTerm(args...)
}

func (t *ConcTermTermList) String() string {
	var b strings.Builder
	b.WriteString("concTerm(")
	var cur TermList = t
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcTerm is Java Gom's ConsconcTerm.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcTerm(head Term, tail TermList) TermList {
	proto := &ConcTermTermList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcTerm"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcTermTermList)
}

// realMakeEmptyConcTerm is Java Gom's EmptyconcTerm.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcTerm() TermList {
	proto := &ConcTermTermList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcTerm"), nil)}
	return factory.Build(proto).(*ConcTermTermList)
}

// RawConcTerm builds the concTerm list holding exactly args, without construction
// hook.
func RawConcTerm(args ...Term) TermList {
	l := realMakeEmptyConcTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcTerm(args[i], l)
	}
	return l
}

// EmptyConcTerm is Java Gom's EmptyconcTerm.make(): the empty concTerm list, after the
// construction hooks.
func EmptyConcTerm() TermList {
	return realMakeEmptyConcTerm()
}

// ConsConcTerm is Java Gom's ConsconcTerm.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcTerm(head Term, tail TermList) TermList {
	return RealMakeConsConcTerm(head, tail)
}

// MakeConcTerm builds the list of args as Tom's `concTerm(args…)` does: from EmptyConcTerm,
// by ConsConcTerm, through the construction hooks (Java's concTerm.fromArray).
func MakeConcTerm(args ...Term) TermList {
	var l TermList = EmptyConcTerm()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcTerm(args[i], l)
	}
	return l
}

// ConcTermFromArray is Java Gom's concTerm.fromArray(array).
func ConcTermFromArray(array []Term) TermList { return MakeConcTerm(array...) }

