// SymbolName is the symbol of the Java term: ConsconcTerm or EmptyconcTerm.
func (t *ConcTermTermList) SymbolName() string {
	if t.empty {
		return "EmptyconcTerm"
	}
	return "ConsconcTerm"
}

func (t *ConcTermTermList) IsConsconcTerm() bool  { return !t.empty }
func (t *ConcTermTermList) IsEmptyconcTerm() bool { return t.empty }

func (t *ConcTermTermList) GetHeadconcTerm() Term {
	if t.empty {
		panic(&aterm.GomError{Msg: "This TermList has no HeadconcTerm"})
	}
	return t.head
}
func (t *ConcTermTermList) GetTailconcTerm() TermList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This TermList has no TailconcTerm"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concTerm list counts as one element).
func (t *ConcTermTermList) Length() int {
	res := 0
	var tl TermList = t
	for {
		c, ok := tl.(*ConcTermTermList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcTermTermList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concTerm list.
func (t *ConcTermTermList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur TermList = t
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcTermTermList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcTerm
// (through the hooks).
func (t *ConcTermTermList) Reverse() TermList {
	if t.empty {
		return t
	}
	var cur TermList = t
	var rev TermList = EmptyConcTerm()
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcTerm(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcTerm (through the hooks).
func (t *ConcTermTermList) Append(element Term) TermList {
	var heads []Term
	var cur TermList = t
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res TermList
	if c, ok := cur.(*ConcTermTermList); ok && c.empty {
		res = ConsConcTerm(element, cur)
	} else {
		res = ConsConcTerm(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcTerm(heads[i], res)
	}
	return res
}

func (t *ConcTermTermList) CompareTo(o any) int {
	for {
		ao := o.(TermList)
		if ao == TermList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcTermTermList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcTermTermList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcTermTermList) CompareToLPO(o any) int {
	for {
		ao := o.(TermList)
		if ao == TermList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcTermTermList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcTermTermList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
// ClassCastException).
func (t *ConcTermTermList) ToATerm() aterm.ATerm {
	f := aterm.GetInstance()
	var heads []Term
	var cur TermList = t
	for {
		c, ok := cur.(*ConcTermTermList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	l := f.MakeListEmpty()
	if c, ok := cur.(*ConcTermTermList); !ok || !c.empty {
		tl, isList := cur.ToATerm().(*aterm.ATermList)
		if !isList {
			panic(&aterm.GomError{Msg: fmt.Sprintf("ClassCastException: the ATerm of %v is not an ATermList", cur)})
		}
		l = tl
	}
	for i := len(heads) - 1; i >= 0; i-- {
		l = f.MakeList(heads[i].ToATerm(), l)
	}
	return l
}

// fromTermConcTermTermList is Java Gom's concTerm.fromTerm: an application of concTerm, or a
// list (of ToATerm), of convertible elements.
func fromTermConcTermTermList(trm aterm.ATerm, conv aterm.ATermConverter) (res TermList, ok bool) {
	trm = conv.Convert(trm)
	if appl, isAppl := trm.(*aterm.ATermAppl); isAppl && appl.GetName() == "concTerm" {
		elems := make([]Term, appl.GetArity())
		for i, a := range appl.GetArguments() {
			elems[i] = TermFromTermConv(a, conv)
		}
		return MakeConcTerm(elems...), true
	}
	if list, isList := trm.(*aterm.ATermList); isList {
		// an element that cannot be converted: not a concTerm (Java returns null)
		defer func() {
			if recover() != nil {
				res, ok = nil, false
			}
		}()
		var elems []Term
		for !list.IsEmpty() {
			elems = append(elems, TermFromTermConv(list.GetFirst(), conv))
			list = list.GetNext()
		}
		return MakeConcTerm(elems...), true
	}
	return nil, false
}

// ExprList is the Go interface backing the Gom sort ExprList.
type ExprList interface {
	sharedobjects.Term
	isExprList()
	// Java Gom API (see the package's generated methods)
	SymbolName() string
	IsConsconcExpr() bool
	IsEmptyconcExpr() bool
	GetHeadconcExpr() Expr
	GetTailconcExpr() ExprList
	Length() int
	Reverse() ExprList
	CompareTo(o any) int
	CompareToLPO(o any) int
	ToATerm() aterm.ATerm
}

// ExprListFromTerm is Java Gom's ExprList.fromTerm(trm).
func ExprListFromTerm(trm aterm.ATerm) ExprList {
	return ExprListFromTermConv(trm, aterm.IdConverter{})
}

// ExprListFromTermConv is Java Gom's ExprList.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func ExprListFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) ExprList {
	converted := conv.Convert(trm)
	var results []ExprList
	if r, ok := fromTermConcExprExprList(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a ExprList", trm), IllegalArgument: true})
	}
	return results[0]
}

// ExprListFromString is Java Gom's ExprList.fromString(s).
func ExprListFromString(s string) ExprList { return ExprListFromTerm(aterm.GetInstance().Parse(s)) }

// ExprListFromStream is Java Gom's ExprList.fromStream(stream) (an IOException is
// the error).
func ExprListFromStream(stream io.Reader) (ExprList, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return ExprListFromTerm(at), nil
}

// ConcExprExprList is the term type of the variadic operator `concExpr(...)` of sort ExprList
// (Java's abstract class concExpr): a maximally-shared cons cell (Java's
// ConsconcExpr: a head and a tail) or the empty list (Java's EmptyconcExpr).
type ConcExprExprList struct {
	head  Expr
	tail  ExprList
	empty bool
	hash  uint32
	// children caches the Visitable children (Java's children field)
	children atomic.Pointer[[]any]
}

func (*ConcExprExprList) isExprList() {}

func (t *ConcExprExprList) Hash() uint32 { return t.hash }

func (t *ConcExprExprList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcExprExprList)
	return ok && t.empty == o.empty && t.head == o.head && t.tail == o.tail
}

func (t *ConcExprExprList) Duplicate() sharedobjects.Term {
	return &ConcExprExprList{head: t.head, tail: t.tail, empty: t.empty, hash: t.hash}
}

// elements returns the cached Visitable children of the list: its
// elements (Java's getChildren, i.e. toArray).
// Java's getChildren is the typed toArray(new Expr[]{}): a last tail
// that is not a list (of sort ExprList) cannot be stored in it
// (ArrayStoreException, a *aterm.GomError here).
func (t *ConcExprExprList) elements() []any {
	if c := t.children.Load(); c != nil {
		return *c
	}
	var cur ExprList = t
	for {
		c, ok := cur.(*ConcExprExprList)
		if !ok || c.empty {
			break
		}
		cur = c.tail
	}
	if c, ok := cur.(*ConcExprExprList); !ok || !c.empty {
		panic(&aterm.GomError{Msg: fmt.Sprintf("ArrayStoreException: the tail %v of a concExpr list is not a Expr", cur)})
	}
	c := t.ToArray()
	t.children.Store(&c)
	return c
}

func (t *ConcExprExprList) ChildCount() int { return len(t.elements()) }

func (t *ConcExprExprList) ChildAt(i int) any { return t.elements()[i] }

func (t *ConcExprExprList) SetChildAt(i int, child any) any {
	dup := t.Children()
	dup[i] = child
	return t.SetChildren(dup)
}

func (t *ConcExprExprList) Children() []any { return append([]any(nil), t.elements()...) }

// SetChildren is Java's setChildren of a list: ConcExprFromArray(children).
func (t *ConcExprExprList) SetChildren(children []any) any {
	args := make([]Expr, len(children))
	for i, c := range children {
		args[i] = c.(Expr)
	}
	return MakeConcExpr(args...)
}

func (t *ConcExprExprList) String() string {
	var b strings.Builder
	b.WriteString("concExpr(")
	var cur ExprList = t
	for {
		c, ok := cur.(*ConcExprExprList)
		if !ok {
			b.WriteString("," + fmt.Sprint(cur))
			break
		}
		if c.empty {
			break
		}
		if c != t {
			b.WriteString(",")
		}
		b.WriteString(fmt.Sprint(c.head))
		cur = c.tail
	}
	b.WriteString(")")
	return b.String()
}

// RealMakeConsConcExpr is Java Gom's ConsconcExpr.realMake: the shared cell of head
// and tail, without hook.
func RealMakeConsConcExpr(head Expr, tail ExprList) ExprList {
	proto := &ConcExprExprList{head: head, tail: tail, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("ConsconcExpr"), []uint32{head.Hash(), tail.Hash()})}
	return factory.Build(proto).(*ConcExprExprList)
}

// realMakeEmptyConcExpr is Java Gom's EmptyconcExpr.realMake: the shared empty list,
// without hook.
func realMakeEmptyConcExpr() ExprList {
	proto := &ConcExprExprList{empty: true, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("EmptyconcExpr"), nil)}
	return factory.Build(proto).(*ConcExprExprList)
}

// RawConcExpr builds the concExpr list holding exactly args, without construction
// hook.
func RawConcExpr(args ...Expr) ExprList {
	l := realMakeEmptyConcExpr()
	for i := len(args) - 1; i >= 0; i-- {
		l = RealMakeConsConcExpr(args[i], l)
	}
	return l
}

// EmptyConcExpr is Java Gom's EmptyconcExpr.make(): the empty concExpr list, after the
// construction hooks.
func EmptyConcExpr() ExprList {
	return realMakeEmptyConcExpr()
}

// ConsConcExpr is Java Gom's ConsconcExpr.make(head, tail): head inserted in front of
// tail, after the construction hooks (theory "" first).
func ConsConcExpr(head Expr, tail ExprList) ExprList {
	return RealMakeConsConcExpr(head, tail)
}

// MakeConcExpr builds the list of args as Tom's `concExpr(args…)` does: from EmptyConcExpr,
// by ConsConcExpr, through the construction hooks (Java's concExpr.fromArray).
func MakeConcExpr(args ...Expr) ExprList {
	var l ExprList = EmptyConcExpr()
	for i := len(args) - 1; i >= 0; i-- {
		l = ConsConcExpr(args[i], l)
	}
	return l
}

// ConcExprFromArray is Java Gom's concExpr.fromArray(array).
func ConcExprFromArray(array []Expr) ExprList { return MakeConcExpr(array...) }

// IsConcExpr is the `Is_concExpr` predicate strategy: succeeds (returns subject
// unchanged) when subject has the `concExpr` shape, otherwise fails with
// sl.ErrVisitFailure.
type IsConcExpr struct{ sl.AbstractStrategy }

func (IsConcExpr) VisitLight(subject any, _ sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcExprExprList); ok {
		return subject, nil
	}
	return subject, sl.ErrVisitFailure
}
func (IsConcExpr) ChildCount() int             { return 0 }
func (IsConcExpr) ChildAt(int) sl.Strategy     { panic("IsConcExpr: no children") }
func (IsConcExpr) SetChildAt(int, sl.Strategy) { panic("IsConcExpr: no children") }
func (s *IsConcExpr) VisitEnv(sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcExprExprList); ok {
		return sl.StatusSuccess
	}
	return sl.StatusFailure
}
func (s *IsConcExpr) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *IsConcExpr) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*IsConcExpr)(nil)

// VisitConcExpr is the `_concExpr` slot-visit strategy: when subject is `concExpr`,
// applies each constituent strategy to the matching child slot and
// rebuilds the term iff at least one child changed. Fails with
// sl.ErrVisitFailure when subject isn't `concExpr`.
type VisitConcExpr struct {
	sl.AbstractStrategy
	args []sl.Strategy
}

// NewVisitConcExpr builds the slot-visit strategy with the supplied per-slot
// sub-strategies.
func NewVisitConcExpr(args ...sl.Strategy) *VisitConcExpr {
	return &VisitConcExpr{args: args}
}

func (s *VisitConcExpr) VisitLight(subject any, intro sl.Introspector) (any, error) {
	if _, ok := subject.(*ConcExprExprList); !ok {
		return subject, sl.ErrVisitFailure
	}
	// Variadic alt: visit every element with args[0] (Java's
	// `_concX` invokes the sub-strategy on each list element).
	if len(s.args) == 0 {
		return subject, nil
	}
	count := intro.GetChildCount(subject)
	var newChildren []any
	for i := 0; i < count; i++ {
		oldChild := intro.GetChildAt(subject, i)
		newChild, err := s.args[0].VisitLight(oldChild, intro)
		if err != nil {
			return subject, err
		}
		if newChildren != nil {
			newChildren[i] = newChild
		} else if newChild != oldChild {
			newChildren = intro.GetChildren(subject)
			newChildren[i] = newChild
		}
	}
	if newChildren != nil {
		return intro.SetChildren(subject, newChildren), nil
	}
	return subject, nil
}

func (s *VisitConcExpr) ChildCount() int                 { return len(s.args) }
func (s *VisitConcExpr) ChildAt(i int) sl.Strategy       { return s.args[i] }
func (s *VisitConcExpr) SetChildAt(i int, v sl.Strategy) { s.args[i] = v }

func (s *VisitConcExpr) VisitEnv(intro sl.Introspector) int {
	if _, ok := s.GetEnvironment().GetSubject().(*ConcExprExprList); !ok {
		return sl.StatusFailure
	}
	return sl.VisitCongruence(s.GetEnvironment(), intro, s.args, true)
}
func (s *VisitConcExpr) Visit(subject any, intro sl.Introspector) (any, error) {
	return sl.VisitStrategy(s, subject, intro)
}
func (s *VisitConcExpr) VisitWith(env *sl.Environment, intro sl.Introspector) (any, error) {
	return sl.VisitStrategyWith(s, env, intro)
}

var _ sl.Strategy = (*VisitConcExpr)(nil)

// SymbolName is the symbol of the Java term: ConsconcExpr or EmptyconcExpr.
func (t *ConcExprExprList) SymbolName() string {
	if t.empty {
		return "EmptyconcExpr"
	}
	return "ConsconcExpr"
}

func (t *ConcExprExprList) IsConsconcExpr() bool  { return !t.empty }
func (t *ConcExprExprList) IsEmptyconcExpr() bool { return t.empty }

func (t *ConcExprExprList) GetHeadconcExpr() Expr {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ExprList has no HeadconcExpr"})
	}
	return t.head
}
func (t *ConcExprExprList) GetTailconcExpr() ExprList {
	if t.empty {
		panic(&aterm.GomError{Msg: "This ExprList has no TailconcExpr"})
	}
	return t.tail
}

// Length is Java's length(): the number of elements of the list (a
// tail that is not a concExpr list counts as one element).
func (t *ConcExprExprList) Length() int {
	res := 0
	var tl ExprList = t
	for {
		c, ok := tl.(*ConcExprExprList)
		if !ok || c.empty {
			return res
		}
		res++
		tl = c.tail
		if _, ok := tl.(*ConcExprExprList); !ok {
			res++
		}
	}
}

// ToArray returns the elements of the list (Java's Object[] toArray()),
// ending with its tail when that is not a concExpr list.
func (t *ConcExprExprList) ToArray() []any {
	out := make([]any, 0, t.Length())
	var cur ExprList = t
	for {
		c, ok := cur.(*ConcExprExprList)
		if !ok || c.empty {
			break
		}
		out = append(out, c.head)
		cur = c.tail
	}
	if c, ok := cur.(*ConcExprExprList); !ok || !c.empty {
		out = append(out, cur)
	}
	return out
}

// Reverse is Java's reverse(): the reversed list, built by ConsConcExpr
// (through the hooks).
func (t *ConcExprExprList) Reverse() ExprList {
	if t.empty {
		return t
	}
	var cur ExprList = t
	var rev ExprList = EmptyConcExpr()
	for {
		c, ok := cur.(*ConcExprExprList)
		if !ok || c.empty {
			break
		}
		rev = ConsConcExpr(c.head, rev)
		cur = c.tail
	}
	return rev
}

// Append is Java's append(element): the list with element added at its
// end, built by ConsConcExpr (through the hooks).
func (t *ConcExprExprList) Append(element Expr) ExprList {
	var heads []Expr
	var cur ExprList = t
	for {
		c, ok := cur.(*ConcExprExprList)
		if !ok || c.empty {
			break
		}
		heads = append(heads, c.head)
		cur = c.tail
	}
	var res ExprList
	if c, ok := cur.(*ConcExprExprList); ok && c.empty {
		res = ConsConcExpr(element, cur)
	} else {
		res = ConsConcExpr(element, cur)
	}
	for i := len(heads) - 1; i >= 0; i-- {
		res = ConsConcExpr(heads[i], res)
	}
	return res
}

func (t *ConcExprExprList) CompareTo(o any) int {
	for {
		ao := o.(ExprList)
		if ao == ExprList(t) {
			return 0
		}
		if t.Hash() != ao.Hash() {
			if t.Hash() < ao.Hash() {
				return -1
			}
			return 1
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcExprExprList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareTo(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcExprExprList)
		if !ok {
			if c := t.tail.CompareTo(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

func (t *ConcExprExprList) CompareToLPO(o any) int {
	for {
		ao := o.(ExprList)
		if ao == ExprList(t) {
			return 0
		}
		if c := strings.Compare(t.SymbolName(), ao.SymbolName()); c != 0 {
			return c
		}
		tco := ao.(*ConcExprExprList)
		if t.empty {
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		if c := t.head.CompareToLPO(tco.head); c != 0 {
			return c
		}
		next, ok := t.tail.(*ConcExprExprList)
		if !ok {
			if c := t.tail.CompareToLPO(tco.tail); c != 0 {
				return c
			}
			panic(&aterm.GomError{Msg: "Unable to compare"})
		}
		t, o = next, tco.tail
	}
}

// ToATerm is Java's toATerm: the list of the elements, ending with the
// ATerm list of the tail (a tail that is not a list is Java's
