// fromTermEbsDeriv is Java Gom's ebs.fromTerm: an unquoted application of
// ebs whose arguments are convertible (as in Java, the arity is not
// checked: a missing argument is an index out of range).
func fromTermEbsDeriv(trm aterm.ATerm, conv aterm.ATermConverter) (Deriv, bool) {
	trm = conv.Convert(trm)
	if appl, ok := trm.(*aterm.ATermAppl); ok && appl.GetName() == "ebs" && !appl.GetAFun().IsQuoted() {
		return MakeEbs(EnvironmentFromTermConv(appl.GetArgument(0), conv), EnvironmentFromTermConv(appl.GetArgument(1), conv)), true
	}
	return nil, false
}

