// DerivTreeFromTerm is Java Gom's DerivTree.fromTerm(trm).
func DerivTreeFromTerm(trm aterm.ATerm) DerivTree {
	return DerivTreeFromTermConv(trm, aterm.IdConverter{})
}

// DerivTreeFromTermConv is Java Gom's DerivTree.fromTerm(trm, atConv): the term of
// the first operator of the sort that converts the ATerm; it panics
// (IllegalArgumentException) when there is none.
func DerivTreeFromTermConv(trm aterm.ATerm, conv aterm.ATermConverter) DerivTree {
	converted := conv.Convert(trm)
	var results []DerivTree
	if r, ok := fromTermEndderivDerivTree(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermDerivruleDerivTree(converted, conv); ok {
		results = append(results, r)
	}
	if r, ok := fromTermDerivrule2DerivTree(converted, conv); ok {
		results = append(results, r)
	}
	if len(results) == 0 {
		panic(&aterm.GomError{Msg: fmt.Sprintf("%v is not a DerivTree", trm), IllegalArgument: true})
	}
	return results[0]
}

// DerivTreeFromString is Java Gom's DerivTree.fromString(s).
func DerivTreeFromString(s string) DerivTree { return DerivTreeFromTerm(aterm.GetInstance().Parse(s)) }

// DerivTreeFromStream is Java Gom's DerivTree.fromStream(stream) (an IOException is
// the error).
func DerivTreeFromStream(stream io.Reader) (DerivTree, error) {
	at, err := aterm.GetInstance().ReadFromTextFile(stream)
	if err != nil {
		return nil, err
	}
	return DerivTreeFromTerm(at), nil
}

